<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); $teamUrl = static fn (string $slug): string => App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/equipes/' . rawurlencode($slug)); ?>
<section class="portal-hero" <?php if (!empty($championship['banner_path'])): ?>style="background-image: linear-gradient(90deg, rgba(10,35,27,.88), rgba(10,35,27,.48)), url('<?= $e($base . '/assets/banner') ?>')"<?php endif; ?>><div><p class="eyebrow"><?= $e($championship['category_name']) ?> · <?= $e($championship['season_name']) ?></p><h1><?= $e($championship['name']) ?></h1><p><?= $e($championship['description'] ?: 'Portal oficial do campeonato.') ?></p><?php if ($currentPhase): ?><span class="portal-badge">Fase atual: <?= $e($currentPhase['name']) ?></span><?php endif; ?></div></section>
<div class="portal-grid portal-grid-main"><section><div class="section-heading"><div><p class="eyebrow">Agenda</p><h2>Proximos confrontos</h2></div><a href="<?= $e($base . '/proximos-jogos') ?>">Ver agenda</a></div><div class="match-cards"><?php foreach ($nextMatches as $match): ?><a class="match-card" href="<?= $e($base . '/partidas/' . $match['id']) ?>"><span><?= $e($match['match_date'] ?: 'A definir') ?> <?= $e(substr((string) ($match['match_time'] ?: ''), 0, 5)) ?></span><strong><?= $e($match['home_team_short_name']) ?> <b>×</b> <?= $e($match['away_team_short_name']) ?></strong><small><?= $e($match['venue_name'] ?: $match['phase_name']) ?></small></a><?php endforeach; ?><?php if (!$nextMatches): ?><p>Nenhum jogo proximo publicado.</p><?php endif; ?></div></section><section><div class="section-heading"><div><p class="eyebrow">Tabela</p><h2>Classificacao</h2></div><a href="<?= $e($base . '/classificacao') ?>">Completa</a></div><?php $shown = 0; foreach ($standings as $row): if ($shown++ >= 6) break; ?><div class="standings-row"><b><?= (int) $row['position'] ?></b><span><?= $e($row['team_short_name'] ?: $row['team_name']) ?></span><strong><?= (int) $row['points'] ?> pts</strong></div><?php endforeach; ?><?php if (!$standings): ?><p>Classificacao ainda nao publicada.</p><?php endif; ?></section></div>
<div class="portal-grid"><section><div class="section-heading"><h2>Ultimos resultados</h2><a href="<?= $e($base . '/resultados') ?>">Ver todos</a></div><div class="result-list"><?php foreach ($results as $match): ?><a href="<?= $e($base . '/partidas/' . $match['id']) ?>"><span><?= $e($match['home_team_short_name']) ?></span><strong><?= (int) $match['home_score'] ?> × <?= (int) $match['away_score'] ?></strong><span><?= $e($match['away_team_short_name']) ?></span></a><?php endforeach; ?><?php if (!$results): ?><p>Nenhum resultado homologado.</p><?php endif; ?></div></section><section><div class="section-heading"><h2>Artilharia</h2><a href="<?= $e($base . '/artilharia') ?>">Ver ranking</a></div><?php foreach ($scorers as $row): ?><div class="ranking-row"><span><?= $e($row['sporting_name'] ?: $row['full_name']) ?><small><?= $e($row['team_name']) ?></small></span><b><?= (int) $row['total'] ?></b></div><?php endforeach; ?><?php if (!$scorers): ?><p>Sem gols homologados.</p><?php endif; ?></section><section><div class="section-heading"><h2>Assistencias</h2><a href="<?= $e($base . '/assistencias') ?>">Ver ranking</a></div><?php foreach ($assists as $row): ?><div class="ranking-row"><span><?= $e($row['sporting_name'] ?: $row['full_name']) ?><small><?= $e($row['team_name']) ?></small></span><b><?= (int) $row['total'] ?></b></div><?php endforeach; ?><?php if (!$assists): ?><p>Sem assistencias homologadas.</p><?php endif; ?></section></div>
<div class="portal-grid"><section><div class="section-heading"><h2>Noticias recentes</h2><a href="<?= $e($base . '/noticias') ?>">Todas</a></div><?php foreach ($news as $item): ?><article class="portal-list-item"><p class="eyebrow"><?= $e($item['published_at']) ?></p><h3><a href="<?= $e($base . '/noticias/' . rawurlencode($item['slug'])) ?>"><?= $e($item['title']) ?></a></h3><p><?= $e($item['summary']) ?></p></article><?php endforeach; ?><?php if (!$news): ?><p>Nenhuma noticia publicada.</p><?php endif; ?></section><section><div class="section-heading"><h2>Vai e Vem</h2><a href="<?= $e($base . '/vai-e-vem') ?>">Todos</a></div><?php foreach ($transfers as $item): ?><div class="portal-list-item"><p class="eyebrow"><?= $e($item['type']) ?> · <?= $e($item['movement_date']) ?></p><h3><?= $e($item['sporting_name'] ?: $item['athlete_name']) ?></h3><p><?= $e($item['previous_team_name'] ?: '-') ?> → <?= $e($item['new_team_name'] ?: '-') ?></p></div><?php endforeach; ?><?php if (!$transfers): ?><p>Nenhuma movimentacao publicada.</p><?php endif; ?></section></div>
<?php if ($knockout): ?><section><div class="section-heading"><h2>Mata-mata</h2><a href="<?= $e($base . '/mata-mata') ?>">Abrir chave</a></div><div class="knockout-strip"><?php foreach (array_slice($knockout, 0, 6) as $tie): ?><div><small><?= $e($tie['stage']) ?></small><strong><?= $e($tie['home_team_name'] ?: $tie['home_source']) ?></strong><span>×</span><strong><?= $e($tie['away_team_name'] ?: $tie['away_source']) ?></strong></div><?php endforeach; ?></div></section><?php endif; ?>
